1	#!/usr/bin/env node
2	// FLEET PANEL — read-mostly web dashboard for the cavecrew bot fleet.
3	//
4	// Standalone Node ESM HTTP server on 127.0.0.1:3200. Zero npm deps, Node
5	// built-ins only. It never touches the runners' internals: it speaks the same
6	// public HTTP API a driver speaks (see cave/DRIVER_GUIDE.md).
7	//
8	// SAFETY CONTRACT — the panel has exactly TWO write actions:
9	//   POST /api/wake {bot}  -> pushes that bot's role-default task, force:false
10	//   POST /api/stop {bot}  -> forwards POST /stop to that bot's runner
11	// force:false is hard-coded and un-overridable, so wake can NEVER preempt a
12	// driver's running task — a busy runner answers 409 and the panel reports it.
13	// No RCON, no chat, no world manipulation, no /eval, no other mutations.
14	//
15	// Docs: cave/PANEL.md
16	import http from 'node:http';
17	import fsp from 'node:fs/promises';
18	import path from 'node:path';
19	import { fileURLToPath } from 'node:url';
20	
21	const HERE = path.dirname(fileURLToPath(import.meta.url));
22	
23	const PANEL_PORT = 3200;
24	// Bind all interfaces: loopback + Tailscale (chief order 2026-09-01). Network
25	// exposure is fenced by the Windows firewall (inbound 3200 scoped to the
26	// tailnet CGNAT range 100.64.0.0/10) — the Host allow-list below stays as
27	// CSRF protection, not as network auth.
28	const PANEL_HOST = process.env.PANEL_HOST || '0.0.0.0';
29	const RUNNER_TIMEOUT_MS = 3000;
30	const FLEET_CACHE_MS = 2000;
31	// The panel polls the fleet on its own timer, whether or not a browser is
32	// attached. Movement deltas are only meaningful if the position ring has been
33	// filling all along, so the page must not be the thing that drives sampling —
34	// otherwise opening the tab shows dashes for the first minute. Request serving
35	// still goes through the FLEET_CACHE_MS cache; this just keeps it warm.
36	const SELF_POLL_MS = 5000;
37	const EVENTS_PER_BOT = 10;
38	const ALERT_LINES = 50;
39	const IRON_QUOTA = 360;
40	
41	// Runner ports. Default is the production fleet 3201-3208; CAVE_PANEL_PORTS
42	// (comma-separated) overrides it so the write paths can be exercised against a
43	// throwaway test runner (e.g. CAVE_PANEL_PORTS=3209) without ever pointing at
44	// a production bot a driver owns.
45	const DEFAULT_PORTS = [3201, 3202, 3203, 3204, 3205, 3206, 3207, 3208];
46	const PORTS = parsePorts(process.env.CAVE_PANEL_PORTS) ?? DEFAULT_PORTS;
47	
48	function parsePorts(raw) {
49	  if (!raw) return null;
50	  const ports = raw
51	    .split(',')
52	    .map((s) => Number(s.trim()))
53	    .filter((n) => Number.isInteger(n) && n > 0 && n < 65536);
54	  return ports.length ? ports : null;
55	}
56	
57	// ---------------------------------------------------------------------------
58	// Fleet roster. Mirrored from cave/overseer.mjs's BOTS list (~line 34) — that
59	// file is the source of truth for role-default tasks, but it is a daemon that
60	// starts its own supervision loop on import, so it cannot be imported here.
61	// Keep this table in sync by hand when overseer's defaults change.
62	//
63	// `defaults` in overseer is a rotation the supervisor cycles through; the WAKE
64	// button pushes defaults[0] so one click is deterministic and predictable.
65	// `team` is the Minecraft team colour from runner.js's TEAM_COLORS (~line 78).
66	// ---------------------------------------------------------------------------
67	const BOTS = [
68	  { name: 'UngaBunga', port: 3201, team: 'yellow',
69	    wake: { ep: '/chop', body: { count: 4, maxDistance: 48 }, say: 'idle: chop wood' } },
70	  { name: 'Grog', port: 3202, team: 'green',
71	    // No /mine default on purpose: /mine's maxDistance is 3D and has tunnelled
72	    // bots downward unattended. Builder role sweeps only.
73	    wake: { ep: '/collect', body: { radius: 16 }, say: 'idle: sweep drops' } },
74	  { name: 'Zug', port: 3203, team: 'light_purple',
75	    wake: { ep: '/collect', body: { radius: 16 }, say: 'idle: sweep drops' } },
76	  { name: 'Bonk', port: 3204, team: 'aqua',
77	    wake: { ep: '/collect', body: { radius: 16 }, say: 'idle: sweep drops' } },
78	  { name: 'Thak', port: 3205, team: 'gold',
79	    wake: { ep: '/mine', body: { block: 'coal_ore', count: 4, maxDistance: 28 }, say: 'idle: dig coal' } },
80	  { name: 'Ook', port: 3206, team: 'red',
81	    wake: { ep: '/collect', body: { radius: 16 }, say: 'idle: sweep drops' } },
82	  { name: 'Durk', port: 3207, team: 'blue',
83	    wake: { ep: '/collect', body: { radius: 16 }, say: 'idle: sweep drops' } },
84	  { name: 'Mog', port: 3208, team: 'dark_aqua',
85	    wake: { ep: '/collect', body: { radius: 16 }, say: 'idle: sweep drops' } },
86	];
87	
88	// Any runner on a port outside the roster (a test bot under CAVE_PANEL_PORTS)
89	// still gets a wake action — the universally safe sweep every roster bot has.
90	const FALLBACK_WAKE = { ep: '/collect', body: { radius: 16 }, say: 'idle: sweep drops' };
91	
92	const BOT_BY_PORT = new Map(BOTS.map((b) => [b.port, b]));
93	const BOT_BY_NAME = new Map(BOTS.map((b) => [b.name.toLowerCase(), b]));
94	
95	// Minecraft chat-colour names -> hex that stays readable on a near-black card.
96	// `blue` and `dark_aqua` are lifted off their literal chat values (#5555FF,
97	// #00AAAA), which go muddy on dark; everything else is the palette value.
98	const TEAM_HEX = {
99	  green: '#5fe36b',
100	  yellow: '#ffe14d',
101	  light_purple: '#e77ff0',
102	  aqua: '#5ff2f2',
103	  gold: '#ffb340',
104	  red: '#ff6b63',
105	  blue: '#7d8dff',
106	  dark_aqua: '#3fd0cf',
107	  white: '#d8dee9',
108	};
109	
110	// ---------------------------------------------------------------------------
111	// Runner polling
112	// ---------------------------------------------------------------------------
113	
114	async function getJson(url) {
115	  const res = await fetch(url, {
116	    signal: AbortSignal.timeout(RUNNER_TIMEOUT_MS),
117	    headers: { accept: 'application/json' },
118	  });
119	  const json = await res.json();
120	  return { status: res.status, json };
121	}
122	
123	async function postJson(url, body) {
124	  const res = await fetch(url, {
125	    method: 'POST',
126	    signal: AbortSignal.timeout(RUNNER_TIMEOUT_MS),
127	    headers: { 'content-type': 'application/json', accept: 'application/json' },
128	    body: JSON.stringify(body ?? {}),
129	  });
130	  let json = null;
131	  try {
132	    json = await res.json();
133	  } catch {
134	    json = null;
135	  }
136	  return { status: res.status, json };
137	}
138	
139	// Per-port rolling event window. /events has no "last N" parameter, so instead
140	// of re-pulling the whole 500-entry ring every 2s we remember each runner's
141	// last seq and ask only for what's new. A runner restart resets its seq, which
142	// shows up as `last` moving backwards — detected below and re-synced from 0.
143	const eventState = new Map(); // port -> { since, window: [], starts: Map(taskId -> ts) }
144	
145	function eventSlot(port) {
146	  let slot = eventState.get(port);
147	  if (!slot) {
148	    slot = { since: 0, window: [], starts: new Map() };
149	    eventState.set(port, slot);
150	  }
151	  return slot;
152	}
153	
154	const TASK_START_RE = /^task (\S+) \(.+\) started$/;
155	
156	async function pollEvents(port) {
157	  const slot = eventSlot(port);
158	  try {
159	    const { status, json } = await getJson(`http://127.0.0.1:${port}/events?since=${slot.since}`);
160	    if (status !== 200 || !json || !Array.isArray(json.events)) return slot.window;
161	    const last = Number(json.last) || 0;
162	    if (last < slot.since) {
163	      // Runner restarted — its ring is fresh and its seq counter went back to
164	      // 1, so the response we're holding was filtered against a `since` from
165	      // the previous run and is empty/meaningless. Drop the stale view, rewind
166	      // to 0 and bail: the NEXT tick refetches the new run from its first
167	      // event. (Falling through here instead would skip seq 1..last forever,
168	      // losing every task-start entry and with it the cards' task ages.)
169	      slot.window = [];
170	      slot.starts.clear();
171	      slot.since = 0;
172	      return slot.window;
173	    }
174	    for (const ev of json.events) {
175	      // Best-effort task age: remember when each task id was announced as
176	      // started, so /status's currentTask (which carries no timestamp) can be
177	      // aged even after its start event has scrolled out of the window.
178	      const m = typeof ev.msg === 'string' ? TASK_START_RE.exec(ev.msg) : null;
179	      if (m) {
180	        slot.starts.set(m[1], ev.ts);
181	        if (slot.starts.size > 50) slot.starts.delete(slot.starts.keys().next().value);
182	      }
183	      slot.window.push(ev);
184	    }
185	    if (slot.window.length > EVENTS_PER_BOT) {
186	      slot.window = slot.window.slice(-EVENTS_PER_BOT);
187	    }
188	    slot.since = Math.max(slot.since, last);
189	  } catch {
190	    // A down or slow runner just keeps whatever window we already had.
191	  }
192	  return slot.window;
193	}
194	
195	async function pollBot(port) {
196	  const roster = BOT_BY_PORT.get(port) ?? null;
197	  const base = {
198	    port,
199	    name: roster?.name ?? `:${port}`,
200	    team: roster?.team ?? 'white',
201	    color: TEAM_HEX[roster?.team ?? 'white'] ?? TEAM_HEX.white,
202	    inRoster: !!roster,
203	  };
204	
205	  let status = null;
206	  let offline = true;
207	  let offlineReason = null;
208	  try {
209	    const res = await getJson(`http://127.0.0.1:${port}/status`);
210	    if (res.status === 200 && res.json && typeof res.json === 'object') {
211	      status = res.json;
212	      offline = false;
213	    } else {
214	      offlineReason = `HTTP ${res.status}`;
215	    }
216	  } catch (err) {
217	    offlineReason = err?.name === 'TimeoutError' ? 'timeout' : (err?.message ?? String(err));
218	  }
219	
220	  if (offline) {
221	    return {
222	      ...base,
223	      offline: true,
224	      offlineReason,
225	      connected: false,
226	      pos: null,
227	      health: null,
228	      food: null,
229	      inventory: [],
230	      currentTask: null,
231	      lastError: null,
232	      deathCount: null,
233	      engine: null,
234	      idle: false,
235	      taskStartedAt: null,
236	      events: eventSlot(port).window,
237	    };
238	  }
239	
240	  const events = await pollEvents(port);
241	  const slot = eventSlot(port);
242	  const task = status.currentTask ?? null;
243	  const running = !!task && task.state === 'running';
244	  // Idle per spec: nothing scheduled, or the last task already finished, or the
245	  // runner is only filling time with its self-issued idle-guard.
246	  const idle = !task || !running || task.kind === 'idle-guard';
247	
248	  return {
249	    ...base,
250	    name: typeof status.name === 'string' && status.name ? status.name : base.name,
251	    offline: false,
252	    offlineReason: null,
253	    connected: !!status.connected,
254	    pos: status.pos ?? null,
255	    health: typeof status.health === 'number' ? status.health : null,
256	    food: typeof status.food === 'number' ? status.food : null,
257	    gamemode: status.gamemode ?? null,
258	    inventory: Array.isArray(status.inventory) ? status.inventory : [],
259	    currentTask: task,
260	    lastError: status.lastError ?? null,
261	    deathCount: typeof status.deathCount === 'number' ? status.deathCount : null,
262	    engine: status.engine ?? null,
263	    idle,
264	    running,
265	    taskStartedAt: task ? (slot.starts.get(task.id) ?? null) : null,
266	    events,
267	  };
268	}
269	
270	let fleetCache = { at: 0, payload: null };
271	let fleetInFlight = null;
272	// Bumped by invalidateFleet(). A buildFleet() captures this at start and only
273	// stamps its result into the cache if it is still current — otherwise a poll
274	// that was already in flight when a wake/stop landed would write its
275	// pre-write snapshot back over the freshly invalidated cache, and the panel
276	// would keep serving the old task state for up to FLEET_CACHE_MS.
277	let fleetGen = 0;
278	
279	function invalidateFleet() {
280	  fleetGen++;
281	  fleetCache = { at: 0, payload: fleetCache.payload };
282	}
283	
284	// ---------------------------------------------------------------------------
285	// Movement deltas — "is this bot actually moving, or is it wedged?"
286	//
287	// Per-bot in-memory ring of timestamped positions, ~65s deep, appended on every
288	// fleet build (client-driven or self-poll alike). A delta is the straight-line
289	// 3D distance from the current position to the sample nearest N seconds ago —
290	// deliberately endpoint-to-endpoint, not path length: it answers "did it get
291	// anywhere", which is the wedge question, and costs one sqrt.
292	//
293	// The ring lives only in this process: it resets when the panel restarts, and
294	// survives browser refreshes (which is the point — the chief's tab being closed
295	// must not blank the history). See SELF_POLL_MS for how it stays warm.
296	// ---------------------------------------------------------------------------
297	const POS_RING_MS = 65_000;
298	// How far off the requested age a sample may be and still count. At the 5s
299	// self-poll cadence the nearest sample is normally within ~2.5s; anything
300	// beyond this means the ring is too young or has a hole, and the honest answer
301	// is null rather than a delta measured over the wrong window.
302	const DELTA_TOLERANCE_MS = 7_500;
303	const posRing = new Map(); // port -> [{ t, x, y, z }] oldest first
304	
305	function samplePosition(port, pos, now) {
306	  let ring = posRing.get(port);
307	  if (!ring) {
308	    ring = [];
309	    posRing.set(port, ring);
310	  }
311	  if (pos && typeof pos.x === 'number') ring.push({ t: now, x: pos.x, y: pos.y, z: pos.z });
312	  const cutoff = now - POS_RING_MS;
313	  while (ring.length && ring[0].t < cutoff) ring.shift();
314	  return ring;
315	}
316	
317	function deltaOver(ring, pos, now, windowMs) {
318	  if (!pos || typeof pos.x !== 'number') return null;
319	  const target = now - windowMs;
320	  let best = null;
321	  let bestGap = Infinity;
322	  for (const s of ring) {
323	    const gap = Math.abs(s.t - target);
324	    if (gap < bestGap) {
325	      bestGap = gap;
326	      best = s;
327	    }
328	  }
329	  // Covers the just-started case too: with only fresh samples in the ring the
330	  // nearest one is ~windowMs away from the target, so this returns null until
331	  // the ring is actually old enough to answer.
332	  if (!best || bestGap > DELTA_TOLERANCE_MS) return null;
333	  const dx = pos.x - best.x;
334	  const dy = pos.y - best.y;
335	  const dz = pos.z - best.z;
336	  return Math.round(Math.sqrt(dx * dx + dy * dy + dz * dz) * 10) / 10;
337	}
338	
339	async function buildFleet() {
340	  const bots = await Promise.all(PORTS.map((p) => pollBot(p).catch((err) => ({
341	    port: p,
342	    name: BOT_BY_PORT.get(p)?.name ?? `:${p}`,
343	    team: BOT_BY_PORT.get(p)?.team ?? 'white',
344	    color: TEAM_HEX[BOT_BY_PORT.get(p)?.team ?? 'white'] ?? TEAM_HEX.white,
345	    offline: true,
346	    offlineReason: err?.message ?? String(err),
347	    connected: false,
348	    pos: null, health: null, food: null, inventory: [],
349	    currentTask: null, lastError: null, deathCount: null, engine: null,
350	    idle: false, taskStartedAt: null, events: [],
351	  }))));
352	
353	  // Feed the position ring and stamp each bot's deltas. Offline bots still get
354	  // a samplePosition() call (with a null pos) so their ring keeps getting
355	  // pruned rather than freezing stale samples that would produce a bogus delta
356	  // the moment the runner comes back.
357	  const now = Date.now();
358	  for (const b of bots) {
359	    const pos = b.offline ? null : b.pos;
360	    const ring = samplePosition(b.port, pos, now);
361	    b.delta30 = deltaOver(ring, pos, now, 30_000);
362	    b.delta60 = deltaOver(ring, pos, now, 60_000);
363	  }
364	
365	  const online = bots.filter((b) => !b.offline);
366	  const iron = bots.reduce((sum, b) => {
367	    const stack = b.inventory.find((i) => i.name === 'iron_ingot');
368	    return sum + (stack ? stack.count : 0);
369	  }, 0);
370	
371	  return {
372	    ts: new Date().toISOString(),
373	    quota: { iron_ingot: IRON_QUOTA },
374	    summary: {
375	      total: PORTS.length,
376	      online: online.length,
377	      idle: online.filter((b) => b.idle).length,
378	      iron_ingot: iron,
379	    },
380	    bots,
381	  };
382	}
383	
384	async function getFleet() {
385	  const now = Date.now();
386	  if (fleetCache.payload && now - fleetCache.at < FLEET_CACHE_MS) return fleetCache.payload;
387	  // Collapse concurrent refreshes onto one poll — a hammered dashboard must not
388	  // multiply into N parallel pokes at every runner.
389	  if (!fleetInFlight) {
390	    const gen = fleetGen;
391	    fleetInFlight = buildFleet()
392	      .then((payload) => {
393	        if (gen === fleetGen) fleetCache = { at: Date.now(), payload };
394	        return payload;
395	      })
396	      .finally(() => {
397	        fleetInFlight = null;
398	      });
399	  }
400	  return fleetInFlight;
401	}
402	
403	// ---------------------------------------------------------------------------
404	// Alerts — tail of the overseer's escalation log.
405	// Written by cave/overseer.mjs to cave/logs/alerts.log; the older cave/alerts.log
406	// path is still checked so either layout works. Missing file is normal, not an
407	// error: it just means nothing has ever escalated.
408	// ---------------------------------------------------------------------------
409	const ALERT_PATHS = [path.join(HERE, 'logs', 'alerts.log'), path.join(HERE, 'alerts.log')];
410	const ALERT_TAIL_BYTES = 256 * 1024;
411	const ALERT_LINE_RE = /^\[([^\]]+)\]\s*(?:ALERT\s*)?(.*)$/;
412	
413	async function readAlerts() {
414	  for (const file of ALERT_PATHS) {
415	    let handle = null;
416	    try {
417	      handle = await fsp.open(file, 'r');
418	      const { size } = await handle.stat();
419	      const start = Math.max(0, size - ALERT_TAIL_BYTES);
420	      const buf = Buffer.alloc(size - start);
421	      if (buf.length) await handle.read(buf, 0, buf.length, start);
422	      const lines = buf.toString('utf8').split(/\r?\n/).filter((l) => l.trim());
423	      // A partial first line is possible when the tail window cut mid-line.
424	      if (start > 0) lines.shift();
425	      return {
426	        file,
427	        alerts: lines.slice(-ALERT_LINES).reverse().map((line) => {
428	          const m = ALERT_LINE_RE.exec(line);
429	          return m ? { ts: m[1], msg: m[2] } : { ts: null, msg: line };
430	        }),
431	      };
432	    } catch {
433	      // try the next candidate path
434	    } finally {
435	      await handle?.close().catch(() => {});
436	    }
437	  }
438	  return { file: null, alerts: [] };
439	}
440	
441	// ---------------------------------------------------------------------------
442	// Write actions — the only two, both narrow.
443	// ---------------------------------------------------------------------------
444	
445	function resolveBot(nameOrPort) {
446	  if (nameOrPort === undefined || nameOrPort === null) return null;
447	  const raw = String(nameOrPort).trim();
448	  if (!raw) return null;
449	  const byName = BOT_BY_NAME.get(raw.toLowerCase());
450	  if (byName && PORTS.includes(byName.port)) return byName;
451	  const asPort = Number(raw.replace(/^:/, ''));
452	  if (Number.isInteger(asPort) && PORTS.includes(asPort)) {
453	    return BOT_BY_PORT.get(asPort) ?? { name: `:${asPort}`, port: asPort, team: 'white', wake: FALLBACK_WAKE };
454	  }
455	  // Named bot that this panel instance isn't watching (e.g. a test runner whose
456	  // name only shows up in /status). Match it against the live fleet by name.
457	  const live = fleetCache.payload?.bots?.find((b) => b.name.toLowerCase() === raw.toLowerCase());
458	  if (live && PORTS.includes(live.port)) {
459	    return BOT_BY_PORT.get(live.port) ?? { name: live.name, port: live.port, team: live.team, wake: FALLBACK_WAKE };
460	  }
461	  return null;
462	}
463	
464	async function doWake(botArg) {
465	  const bot = resolveBot(botArg);
466	  if (!bot) return { status: 404, body: { ok: false, error: `unknown bot "${botArg}" (not on this panel's port list)` } };
467	
468	  const plan = bot.wake ?? FALLBACK_WAKE;
469	  // force:false is built here, not copied from the plan and not read from the
470	  // request — there is no code path in this file that can send force:true.
471	  const body = { ...plan.body, force: false };
472	
473	  try {
474	    const { status, json } = await postJson(`http://127.0.0.1:${bot.port}${plan.ep}`, body);
475	    if (status === 409) {
476	      return {
477	        status: 200,
478	        body: {
479	          ok: false,
480	          busy: true,
481	          message: 'busy, not preempted',
482	          bot: bot.name,
483	          currentTask: json?.currentTask ?? null,
484	        },
485	      };
486	    }
487	    if (status !== 200) {
488	      return {
489	        status: 200,
490	        body: { ok: false, bot: bot.name, error: json?.error ?? `runner HTTP ${status}`, httpStatus: status },
491	      };
492	    }
493	    return {
494	      status: 200,
495	      body: {
496	        ok: true,
497	        bot: bot.name,
498	        port: bot.port,
499	        pushed: { ep: plan.ep, body, say: plan.say },
500	        task: json?.task ?? null,
501	      },
502	    };
503	  } catch (err) {
504	    return { status: 200, body: { ok: false, bot: bot.name, error: err?.message ?? String(err) } };
505	  }
506	}
507	
508	async function doStop(botArg) {
509	  const bot = resolveBot(botArg);
510	  if (!bot) return { status: 404, body: { ok: false, error: `unknown bot "${botArg}" (not on this panel's port list)` } };
511	  try {
512	    const { status, json } = await postJson(`http://127.0.0.1:${bot.port}/stop`, {});
513	    if (status !== 200) {
514	      return { status: 200, body: { ok: false, bot: bot.name, error: json?.error ?? `runner HTTP ${status}`, httpStatus: status } };
515	    }
516	    return { status: 200, body: { ok: true, bot: bot.name, port: bot.port, task: json?.task ?? null } };
517	  } catch (err) {
518	    return { status: 200, body: { ok: false, bot: bot.name, error: err?.message ?? String(err) } };
519	  }
520	}
521	
522	// ---------------------------------------------------------------------------
523	// HTTP plumbing
524	// ---------------------------------------------------------------------------
525	
526	function sendJson(res, status, obj) {
527	  const body = JSON.stringify(obj);
528	  res.writeHead(status, {
529	    'content-type': 'application/json; charset=utf-8',
530	    'content-length': Buffer.byteLength(body),
531	    'cache-control': 'no-store',
532	  });
533	  res.end(body);
534	}
