565	// CSRF / DNS-rebinding guard. Binding to 127.0.0.1 keeps other machines out
566	// but does NOT keep out a random web page the operator happens to have open:
567	// the browser will happily issue cross-origin requests at localhost. Two
568	// layers close that, and both are needed:
569	//
570	//  1. Host allow-list — a hostile page can point a domain it controls at
571	//     127.0.0.1 (DNS rebinding) and reach this server with its own origin's
572	//     privileges. Such a request still carries that attacker hostname in the
573	//     Host header, so anything but our own loopback names is refused.
574	//  2. Content-type gate on writes — text/plain, form-urlencoded and multipart
575	//     are CORS-"simple" request types: a page can POST them cross-origin with
576	//     no preflight at all, and `mode:'no-cors'` hides the response while the
577	//     mutation still lands. Requiring application/json forces a preflight,
578	//     and since this server sends no CORS headers the preflight fails and the
579	//     request never arrives.
580	const ALLOWED_HOSTS = new Set([
581	  `127.0.0.1:${PANEL_PORT}`,
582	  `localhost:${PANEL_PORT}`,
583	  `[::1]:${PANEL_PORT}`,
584	  `zetpc:${PANEL_PORT}`,
585	  `zetpc.tail5d7e78.ts.net:${PANEL_PORT}`,
586	]);
587	// Tailscale CGNAT IPs (100.64.0.0/10) are legitimate Host values when a
588	// tailnet device opens the panel by IP.
589	const TAILNET_HOST_RE = new RegExp('^100([.][0-9]{1,3}){3}:' + PANEL_PORT + '$');
590	
591	function hostAllowed(req) {
592	  const host = req.headers.host;
593	  if (typeof host !== 'string') return false;
594	  const h = host.toLowerCase();
595	  return ALLOWED_HOSTS.has(h) || TAILNET_HOST_RE.test(h);
596	}
597	
598	function isJsonRequest(req) {
599	  const ct = req.headers['content-type'];
600	  return typeof ct === 'string' && ct.split(';')[0].trim().toLowerCase() === 'application/json';
601	}
602	
603	async function handle(req, res) {
604	  const url = new URL(req.url, `http://${PANEL_HOST}:${PANEL_PORT}`);
605	  const p = url.pathname;
606	  const m = req.method;
607	
608	  if (!hostAllowed(req)) {
609	    return sendJson(res, 403, { error: 'forbidden host — panel only answers to its own loopback origin' });
610	  }
611	
612	  if (m === 'GET' && (p === '/' || p === '/index.html')) {
613	    const html = renderPage();
614	    res.writeHead(200, {
615	      'content-type': 'text/html; charset=utf-8',
616	      'content-length': Buffer.byteLength(html),
617	      'cache-control': 'no-store',
618	    });
619	    return res.end(html);
620	  }
621	
622	  if (m === 'GET' && p === '/api/fleet') {
623	    return sendJson(res, 200, await getFleet());
624	  }
625	
626	  if (m === 'GET' && p === '/api/alerts') {
627	    return sendJson(res, 200, await readAlerts());
628	  }
629	
630	  if (m === 'POST' && (p === '/api/wake' || p === '/api/stop')) {
631	    // Checked before the body is even read, and long before anything is
632	    // forwarded to a runner: a rejected request never touches a bot.
633	    if (!isJsonRequest(req)) {
634	      return sendJson(res, 415, { ok: false, error: 'content-type must be application/json' });
635	    }
636	    let body;
637	    try {
638	      body = await readBody(req);
639	    } catch (err) {
640	      return sendJson(res, 400, { ok: false, error: err.message });
641	    }
642	    const out = p === '/api/wake' ? await doWake(body.bot) : await doStop(body.bot);
643	    // A write invalidates the cache so the next poll shows the new state.
644	    invalidateFleet();
645	    return sendJson(res, out.status, out.body);
646	  }
647	
648	  return sendJson(res, 404, { error: 'not found' });
649	}
