  : Infinity;
const deepBelowCamp = pos ? PANIC_CAMP_POS.y - pos.y > PANIC_DEEP_DELTA : false;
const farOrDeep = distFromCamp > PANIC_FAR_RADIUS || deepBelowCamp;

try {
